public class BrokenPoint {
    final int x, y;
    BrokenPoint(int x, int y) { this.x = x; this.y = y; }

    // BUG: Overload! Not an override of Object.equals(Object)
    public boolean equals(BrokenPoint other) {
        return this.x == other.x && this.y == other.y;
    }
}

Set<BrokenPoint> set = new HashSet<>();
set.add(new BrokenPoint(1, 2));
// Returns FALSE because HashSet calls equals(Object)!
System.out.println(set.contains(new BrokenPoint(1, 2)));

double nan1 = Double.NaN;
double nan2 = Double.NaN;
System.out.println(nan1 == nan2); // false (IEEE 754)
System.out.println(Double.compare(nan1, nan2) == 0); // true (Consistent object equality)

// Also handles signed zeros:
double zero = 0.0;
double negZero = -0.0;
System.out.println(zero == negZero); // true
System.out.println(Double.compare(zero, negZero) == 0); // false (-0.0 < 0.0)

public record Range(int low, int high) {
    // Compact constructor:
    public Range {
        if (low > high) {
            throw new IllegalArgumentException("low (" + low + ") > high (" + high + ")");
        }
        // Compiler automatically does: this.low = low; this.high = high;
    }
}

package com.example.service;

public class AccountService {
    // Package-private: visible to other classes in com.example.service,
    // but hidden from outside packages.
    void internalAuditLog(String action) {
        System.out.println("Audit: " + action);
    }
}

public sealed interface Shape permits Circle, Square, Polygon {}

// 1. final: terminates hierarchy
public final class Circle implements Shape {}

// 2. record: implicitly final
public record Square(double side) implements Shape {}

// 3. non-sealed: allows open extension
public non-sealed class Polygon implements Shape {}

static String format(Object obj) {
    return switch (obj) {
        case null -> "Value was null"; // Handles null safely!
        case Integer i -> "Integer: " + i;
        case String s  -> "String: " + s;
        default        -> "Unknown object";
    };
}

public class AnimalProducer {
    public Animal produce() { return new Animal(); }
}

public class DogProducer extends AnimalProducer {
    // Covariant return type: Dog is a subtype of Animal
    @Override
    public Dog produce() { return new Dog(); }
}

DogProducer dp = new DogProducer();
Dog myDog = dp.produce(); // No cast needed!

public class Counter {
    // One shared copy on the heap for the entire class:
    public static int globalCount = 0;

    // Allocated on the heap inside each new Counter instance:
    public int instanceCount = 0;
}
